#include <zephyr/rtio/work.h>
#include <zephyr/kernel.h>

#define WORK_QUEUE_STACK_SIZE CONFIG_RTIO_WORKQ_STACK_SIZE
#define WORK_QUEUE_PRIO CONFIG_RTIO_WORKQ_PRIO

K_THREAD_STACK_DEFINE(workq_stack, WORK_QUEUE_STACK_SIZE);
static struct k_work_q workq;

K_MEM_SLAB_DEFINE_STATIC(work_items,
			 sizeof(struct rtio_work_req),
			 CONFIG_RTIO_WORKQ_POOL_ITEMS,
			 4);

static void work_handler(struct k_work *work)
{
	struct k_work_p4wq *work_item = CONTAINER_OF(work,
						     struct k_work_p4wq,
						     work);
	struct rtio_work_req *req = CONTAINER_OF(work_item,
						 struct rtio_work_req,
						 work);

	req->handler(req->iodev_sqe);

	rtio_work_req_free(req);
}

static int rtio_workq_init(void)
{
	struct k_work_queue_config cfg = {
		.name = "rtio_workq",
		.no_yield = IS_ENABLED(CONFIG_RTIO_WORKQ_NO_YIELD),
	};

	k_work_queue_init(&workq);
	k_work_queue_start(&workq,
			   workq_stack,
			   K_THREAD_STACK_SIZEOF(workq_stack),
			   WORK_QUEUE_PRIO,
			   &cfg);

	return 0;
}

struct rtio_work_req *rtio_work_req_alloc(void)
{
	struct rtio_work_req *req;
	int err;

	err = k_mem_slab_alloc(&work_items, (void **)&req, K_NO_WAIT);
	if (err) {
		return NULL;
	}

	(void)memset(req, 0, sizeof(struct rtio_work_req));

	k_work_init(&req->work.work, work_handler);

	return req;
}

void rtio_work_req_submit(struct rtio_work_req *req,
			  struct rtio_iodev_sqe *iodev_sqe,
			  rtio_work_submit_t handler)
{
	if (!req) {
		return;
	}

	if (!iodev_sqe || !handler) {
		rtio_work_req_free(req);
		return;
	}

	req->iodev_sqe = iodev_sqe;
	req->handler = handler;

	k_work_submit_to_queue(&workq, &req->work.work);
}

void rtio_work_req_free(struct rtio_work_req *req)
{
	k_mem_slab_free(&work_items, (void *)req);
}

uint32_t rtio_work_req_used_count_get(void)
{
	return k_mem_slab_num_used_get(&work_items);
}

SYS_INIT(rtio_workq_init, POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);
